import type { Metadata } from 'next';
import { Geist, Geist_Mono } from 'next/font/google';
import './globals.css';

const geistSans = Geist({ variable: '--font-geist-sans', subsets: ['latin'] });
const geistMono = Geist_Mono({ variable: '--font-geist-mono', subsets: ['latin'] });

export const metadata: Metadata = {
  title: 'Candidate Search',
  description: 'Search a library of software engineering candidates.',
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en" className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}>
      <body className="flex min-h-full flex-col font-sans">{children}</body>
    </html>
  );
}
import { and, asc, count, desc, eq, gte, inArray, lte, ne, sql, type SQL } from 'drizzle-orm';
import { db } from '@/db';
import {
  candidateSkillTable,
  candidateTable,
  type Candidate,
  type CandidateSkill,
} from '@/db/schema';
import type {
  CandidateSummary,
  FilterOptions,
  MatchReason,
  SearchFilters,
  SearchResponse,
} from '@/lib/contracts';

const TOP_N = 10;
const TOP_SKILLS = 8;

const usd = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});

/** Evidence strength of one skill row: roles mentioning it, plus one for the bio. */
const strength = (row: CandidateSkill) => row.roleCount + (row.inBio ? 1 : 0);

/** Filter search (spec: docs/slices/S3-filter-search.md). Top 10 by skill score. */
export async function searchCandidates(filters: SearchFilters): Promise<SearchResponse> {
  const c = candidateTable;
  const cs = candidateSkillTable;
  const { countries, skills, minYears, maxYears, minSalary, maxSalary } = filters;

  const conditions: (SQL | undefined)[] = [];
  if (countries.length > 0) {
    conditions.push(
      inArray(
        sql`lower(${c.country})`,
        countries.map((country) => country.toLowerCase())
      )
    );
  }
  if (minYears !== null) conditions.push(gte(c.yearsExperience, minYears));
  if (maxYears !== null) conditions.push(lte(c.yearsExperience, maxYears));
  if (minSalary !== null || maxSalary !== null) {
    const annual = sql`${c.fullTimeRateNormalized} * 12`;
    conditions.push(eq(c.rateUnverified, false));
    if (minSalary !== null) conditions.push(gte(annual, minSalary));
    if (maxSalary !== null) conditions.push(lte(annual, maxSalary));
  }

  // Candidates with every requested skill, scored by summed evidence strength.
  const matched = db
    .select({
      candidateId: cs.candidateId,
      score: sql<number>`sum(${cs.roleCount} + ${cs.inBio})`.as('score'),
    })
    .from(cs)
    .where(inArray(cs.skill, skills))
    .groupBy(cs.candidateId)
    .having(sql`count(*) = ${skills.length}`)
    .as('matched');

  // With no skills every score is 0, so the order starts at years of experience.
  const hasSkills = skills.length > 0;
  const score = hasSkills ? matched.score : sql<number>`0`;
  const base = db
    .select({ candidate: c, score, total: sql<number>`count(*) over ()` })
    .from(c)
    .$dynamic();
  if (hasSkills) base.innerJoin(matched, eq(matched.candidateId, c.id));

  const rows = await base
    .where(and(...conditions))
    .orderBy(...(hasSkills ? [desc(score)] : []), desc(c.yearsExperience), asc(c.id))
    .limit(TOP_N);

  const skillRows = rows.length
    ? await db
        .select()
        .from(cs)
        .where(
          inArray(
            cs.candidateId,
            rows.map((row) => row.candidate.id)
          )
        )
    : [];

  const results = rows.map(({ candidate, score }) => {
    const own = skillRows.filter((row) => row.candidateId === candidate.id);
    const reasons: MatchReason[] = skills.map((skill) => ({
      kind: 'skill',
      label: skillLabel(own.find((row) => row.skill === skill)),
    }));
    reasons.push({ kind: 'experience', label: experienceLabel(candidate, filters) });
    if (minSalary !== null || maxSalary !== null) {
      reasons.push({ kind: 'salary', label: salaryLabel(candidate, filters) });
    }
    if (countries.length > 0) {
      reasons.push({ kind: 'country', label: `Based in ${candidate.country}` });
    }
    return {
      candidate: toSummary(candidate, own),
      score: Number(score),
      matchedSkills: [...skills],
      reasons,
    };
  });

  return { filters, total: rows[0]?.total ?? 0, results };
}

/** Countries (except "-") and skills with candidate counts, most common first. */
export async function getFilterOptions(): Promise<FilterOptions> {
  const c = candidateTable;
  const cs = candidateSkillTable;
  const countries = await db
    .select({ name: c.country, count: count() })
    .from(c)
    .where(ne(c.country, '-'))
    .groupBy(c.country)
    .orderBy(desc(count()), asc(c.country));
  const skills = await db
    .select({ name: cs.skill, count: count() })
    .from(cs)
    .groupBy(cs.skill)
    .orderBy(desc(count()), asc(cs.skill));
  return { countries, skills };
}

function toSummary(candidate: Candidate, skills: CandidateSkill[]): CandidateSummary {
  const topSkills = [...skills]
    .sort(
      (a, b) => strength(b) - strength(a) || (a.skill < b.skill ? -1 : a.skill > b.skill ? 1 : 0)
    )
    .slice(0, TOP_SKILLS)
    .map((row) => row.skill);
  return {
    id: candidate.id,
    name: `${candidate.firstName} ${candidate.lastName}`,
    country: candidate.country,
    yearsExperience: candidate.yearsExperience,
    monthlyRate: candidate.fullTimeRateNormalized,
    rateUnverified: candidate.rateUnverified,
    availability: {
      fullTime: candidate.fullTime,
      partTime: candidate.partTime,
      contractor: candidate.contractor,
      employee: candidate.employee,
    },
    biography: candidate.biography ?? '',
    topSkills,
  };
}

function skillLabel(row: CandidateSkill | undefined): string {
  if (!row) return '';
  const roles = `${row.roleCount} ${row.roleCount === 1 ? 'role' : 'roles'}`;
  if (row.roleCount > 0) return `${row.skill} in ${roles}${row.inBio ? ' and bio' : ''}`;
  return `${row.skill} in bio`;
}

function experienceLabel(candidate: Candidate, { minYears, maxYears }: SearchFilters): string {
  const label = `${candidate.yearsExperience} yrs experience`;
  if (minYears !== null && maxYears !== null) return `${label} (${minYears}–${maxYears})`;
  if (minYears !== null) return `${label} (min ${minYears})`;
  if (maxYears !== null) return `${label} (max ${maxYears})`;
  return label;
}

function salaryLabel(candidate: Candidate, { minSalary, maxSalary }: SearchFilters): string {
  const label = `${usd.format((candidate.fullTimeRateNormalized ?? 0) * 12)}/yr`;
  if (minSalary !== null && maxSalary !== null) {
    return `${label}, within ${usd.format(minSalary)}–${usd.format(maxSalary)}`;
  }
  if (maxSalary !== null) return `${label}, under ${usd.format(maxSalary)}`;
  return `${label}, over ${usd.format(minSalary ?? 0)}`;
}
import { asc, eq } from 'drizzle-orm';
import { db } from '@/db';
import {
  candidateSkillTable,
  candidateTable,
  educationTable,
  experienceTable,
  type Candidate,
  type CandidateSkill,
} from '@/db/schema';
import type {
  CandidateProfile,
  CandidateSummary,
  ProfileEducation,
  ProfileExperience,
  ProfileSkill,
} from '@/lib/contracts';
import { resolveJobs } from '@/lib/derive/experience';

const TOP_SKILLS = 8;

/** Candidate profile (spec: docs/slices/S6-profile-page.md). null for an unknown id. */
export async function getCandidateProfile(id: number): Promise<CandidateProfile | null> {
  const [candidates, experienceRows, educationRows, skillRows] = await Promise.all([
    db.select().from(candidateTable).where(eq(candidateTable.id, id)).limit(1),
    db
      .select()
      .from(experienceTable)
      .where(eq(experienceTable.candidateId, id))
      .orderBy(asc(experienceTable.id)),
    db
      .select()
      .from(educationTable)
      .where(eq(educationTable.candidateId, id))
      .orderBy(asc(educationTable.id)),
    db.select().from(candidateSkillTable).where(eq(candidateSkillTable.candidateId, id)),
  ]);
  const candidate = candidates[0];
  if (!candidate) return null;

  const resolved = resolveJobs(experienceRows, new Date());
  const experiences = byStartDesc(
    experienceRows.map((row, i): ProfileExperience => ({
      company: row.company,
      position: row.position,
      description: row.description ?? '',
      startDate: isoDate(row.startDate),
      endDate: isoDate(row.endDate),
      effectiveEndDate: isoDate(resolved[i].effectiveEndDate),
      counted: resolved[i].counted,
      excludedReason: resolved[i].excludedReason,
    })),
    experienceRows.map((row) => row.startDate)
  );

  const education = byStartDesc(
    educationRows.map((row): ProfileEducation => ({
      school: row.school,
      degree: row.degree.trim(),
      startDate: isoDate(row.startDate),
      endDate: isoDate(row.endDate),
    })),
    educationRows.map((row) => row.startDate)
  );

  const skills: ProfileSkill[] = sortSkills(skillRows).map((row) => ({
    name: row.skill,
    inBio: row.inBio,
    roleCount: row.roleCount,
  }));

  return {
    candidate: toSummary(
      candidate,
      skills.slice(0, TOP_SKILLS).map((skill) => skill.name)
    ),
    partTimeMonthlyRate: candidate.partTimeRateNormalized,
    experiences,
    education,
    skills,
  };
}

/** UTC `YYYY-MM-DD`, or null. */
const isoDate = (date: Date | null) => (date ? date.toISOString().slice(0, 10) : null);

/** Newest start first, null starts last; stable, so ties keep input order. */
function byStartDesc<T>(items: T[], starts: (Date | null)[]): T[] {
  const time = (i: number) => starts[i]?.getTime() ?? -Infinity;
  return items
    .map((_, i) => i)
    .sort((a, b) => (time(a) === time(b) ? 0 : time(b) > time(a) ? 1 : -1))
    .map((i) => items[i]);
}

/** Strongest evidence first (roles + bio), then by name using the default JS sort order. */
function sortSkills(rows: CandidateSkill[]): CandidateSkill[] {
  const strength = (row: CandidateSkill) => row.roleCount + (row.inBio ? 1 : 0);
  return [...rows].sort(
    (a, b) => strength(b) - strength(a) || (a.skill < b.skill ? -1 : a.skill > b.skill ? 1 : 0)
  );
}

// Private copy of the S3 CandidateSummary mapping; merged into one helper after wave 2.
function toSummary(candidate: Candidate, topSkills: string[]): CandidateSummary {
  return {
    id: candidate.id,
    name: `${candidate.firstName} ${candidate.lastName}`,
    country: candidate.country,
    yearsExperience: candidate.yearsExperience,
    monthlyRate: candidate.fullTimeRateNormalized,
    rateUnverified: candidate.rateUnverified,
    availability: {
      fullTime: candidate.fullTime,
      partTime: candidate.partTime,
      contractor: candidate.contractor,
      employee: candidate.employee,
    },
    biography: candidate.biography ?? '',
    topSkills,
  };
}
